local function BuildClassicRows(idField, records, defaultTip)
    local rows = {}
    for _, record in ipairs(records) do
        local row = {
            name = record[2],
            source = record[3],
            acquisition = record[7] or ("Obtain " .. record[2] .. " from " .. record[3] .. "."),
            tips = record[8] or defaultTip,
            waypoints = CLASSIC_WAYPOINTS[record[4]],
            category = record[5],
            npcId = record[6],
            detailKey = record[9],
        }
        row[idField] = record[1]
        rows[#rows + 1] = row
    end
    return rows
end

